const upsertFleetCredentialProfile = `-- name: UpsertFleetCredentialProfile :one
INSERT INTO fleet_credential_profile (owner_id, profile_name, config_version)
VALUES ($1, $2, $3)
ON CONFLICT (owner_id) DO UPDATE
SET profile_name = EXCLUDED.profile_name, config_version = EXCLUDED.config_version, updated_at = now()
RETURNING id, owner_id, profile_name, config_version, created_at, updated_at
`

type UpsertFleetCredentialProfileParams struct {
	OwnerID       pgtype.UUID `json:"owner_id"`
	ProfileName   string      `json:"profile_name"`
	ConfigVersion string      `json:"config_version"`
}

func (q *Queries) UpsertFleetCredentialProfile(ctx context.Context, arg UpsertFleetCredentialProfileParams) (FleetCredentialProfile, error) {
	row := q.db.QueryRow(ctx, upsertFleetCredentialProfile, arg.OwnerID, arg.ProfileName, arg.ConfigVersion)
	var i FleetCredentialProfile
	err := row.Scan(
		&i.ID,
		&i.OwnerID,
		&i.ProfileName,
		&i.ConfigVersion,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
